from functools import cmp_to_key
from typing import List

def minimizeTotalTime(multiples: List[int], prices: List[int]) -> List[int]:
    # a 排在 b 前面更好 <=> p_a·m_a·(m_b-1) < p_b·m_b·(m_a-1)，交叉相乘避免浮点和除以 0
    def cmp(a: int, b: int) -> int:
        left = prices[a] * multiples[a] * (multiples[b] - 1)
        right = prices[b] * multiples[b] * (multiples[a] - 1)
        return -1 if left < right else (1 if left > right else 0)
    return sorted(range(len(prices)), key=cmp_to_key(cmp))
